pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address nonOwner = address(0x1234);
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(0x5678);
        bool success;
        vm.prank(nonOwner);
        try c.addReward(rewardToken) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false);
    }
}
